243	        new(new ClaimsIdentity(
244	            [
245	                new Claim("sub", $"google-sub-{userId:N}"),
246	                new Claim("email", email),
247	                new Claim("user_id", userId.ToString()),
248	                new Claim("system_role", "standard"),
249	            ],
250	            TestAuthenticationHandler.SchemeName));
251	
