256	        string email,
257	        string? googleSub = null,
258	        string displayName = "Test Invitee") =>
259	        new(new ClaimsIdentity(
260	            [
261	                new Claim("sub", googleSub ?? $"google-sub-{email}"),
262	                new Claim("email", email),
263	                new Claim("name", displayName),
264	            ],
265	            TestAuthenticationHandler.SchemeName));
266	}
