    {
        Verify.That(boardId).IsNotDefault();
        Verify.That(tx).IsNotNull();

        const string sql = "DELETE FROM boards WHERE id = @boardId";
        await _connection.ExecuteAsync(sql, new { boardId = boardId.ToString("D") }, transaction: tx);
    }
}

